/** Wrap the app's screens in this to show onboarding on first launch (a `platform` change). */
export { ConsentGate } from "./components/ConsentGate";
export type { ConsentType } from "./consent";
/** Consent checks for other features: ask iOS for a permission only once `useHasConsent` is true. */
export { type ConsentState, useConsent, useHasConsent } from "./hooks/useAccount";
export { AccountScreen } from "./screens/AccountScreen";
import type { ConsentChoices, DeleteEverythingResult } from "@kip/shared/account";
import type { TravellerProfile } from "@kip/shared/domain";
import { useMutation, useMutationState, useQuery, useQueryClient } from "@tanstack/react-query";
import { useTRPC, useTRPCClient } from "@/lib/trpc";
import { accountCache } from "../cache";
import {
  type AccountState,
  accountState,
  type ConsentType,
  consentOf,
  hasAnswered,
  saveOnboarding,
} from "../consent";

/** `account.me`. The gate, the Account tab and every consent check share this one query. */
export function useAccount(): AccountState {
  const trpc = useTRPC();
  const me = useQuery({ ...trpc.account.me.queryOptions(), retry: 1 });
  return accountState(me.data, me.isError, () => void me.refetch());
}

export type ConsentState = {
  /** What the user said yes to. Every type is false until they answer, and while loading or offline */
  consent: ConsentChoices;
  /** The user has made their choices at least once */
  answered: boolean;
  loading: boolean;
};

/** The user's consent per data type. Use `consent` as the `consent` flags of a night upload. */
export function useConsent(): ConsentState {
  const state = useAccount();
  const view = state.status === "ready" || state.status === "onboarding" ? state.view : undefined;
  return {
    consent: consentOf(view),
    answered: hasAnswered(view),
    loading: state.status === "loading",
  };
}

/**
 * True only once the user has said yes to `type` in Kip. Ask iOS for the matching permission
 * (microphone, HealthKit, location) only while this is true.
 */
export function useHasConsent(type: ConsentType): boolean {
  return useConsent().consent[type];
}

function useAccountCache() {
  const trpc = useTRPC();
  return accountCache(useQueryClient(), trpc.account.me.queryKey());
}

/** Saves the onboarding answers: the profile, then consent (see `saveOnboarding`). */
export function useFinishOnboarding() {
  const client = useTRPCClient();
  const cache = useAccountCache();
  return useMutation({
    mutationFn: (answers: { consent: ConsentChoices; profile: TravellerProfile | null }) =>
      saveOnboarding(
        {
          setProfile: async (input) => {
            const view = await client.account.setProfile.mutate(input);
            // If the consent write then fails, onboarding shows the profile that is stored.
            await cache.write(view);
            return view;
          },
          setConsent: (input) => client.account.setConsent.mutate(input),
        },
        answers,
      ),
    onSuccess: cache.write,
  });
}

// The Account tab allows one account write at a time (AccountSettings), so responses cannot
// arrive out of order, and nothing is saved while a delete runs.

export function useSaveConsent() {
  const trpc = useTRPC();
  const cache = useAccountCache();
  return useMutation(trpc.account.setConsent.mutationOptions({ onSuccess: cache.write }));
}

export function useSaveProfile() {
  const trpc = useTRPC();
  const cache = useAccountCache();
  return useMutation(trpc.account.setProfile.mutationOptions({ onSuccess: cache.write }));
}

/**
 * Deletes everything on the server, then resets every cached query, so nothing of the old data
 * stays on screen and every consent reads as off until the user answers again.
 */
export function useDeleteEverything() {
  const trpc = useTRPC();
  const cache = useAccountCache();
  return useMutation(
    trpc.account.deleteEverything.mutationOptions({
      onSuccess: () => {
        void cache.forget();
      },
    }),
  );
}

export type DeleteMutation = ReturnType<typeof useDeleteEverything>;

/** The latest successful "delete everything", for the notice above onboarding. */
export function useLastDeletion(): DeleteEverythingResult | undefined {
  const trpc = useTRPC();
  const results = useMutationState({
    filters: { mutationKey: trpc.account.deleteEverything.mutationKey(), status: "success" },
    select: (mutation) => mutation.state.data as DeleteEverythingResult | undefined,
  });
  return results.at(-1);
}
import {
  type AccountView,
  type ConsentChoices,
  NO_CONSENT,
  type SetConsentInput,
  type SetProfileInput,
} from "@kip/shared/account";
import type { TravellerProfile } from "@kip/shared/domain";

// Pure account logic: no React, no network. docs/DOMAIN.md, Privacy: one explicit consent per
// data type, and nothing is consented to until the user answers.

export type ConsentType = keyof ConsentChoices;

/** The order onboarding asks in. */
export const CONSENT_TYPES = [
  "microphone",
  "health",
  "location",
] as const satisfies readonly ConsentType[];

/** True once the user has made their consent choices. Until then, onboarding shows. */
export function hasAnswered(view: AccountView | undefined): boolean {
  return view !== undefined && view.consentUpdatedAt !== null;
}

/** What the user said yes to. Every type is off until they answer, and while unknown. */
export function consentOf(view: AccountView | undefined): ConsentChoices {
  return view && hasAnswered(view) ? view.consent : NO_CONSENT;
}

export type AccountState =
  | { status: "loading" }
  | { status: "error"; retry: () => void }
  | { status: "onboarding"; view: AccountView }
  | { status: "ready"; view: AccountView };

/** Cached data wins over a failed refetch, so a flaky connection never reopens onboarding. */
export function accountState(
  view: AccountView | undefined,
  failed: boolean,
  retry: () => void,
): AccountState {
  if (view) return hasAnswered(view) ? { status: "ready", view } : { status: "onboarding", view };
  return failed ? { status: "error", retry } : { status: "loading" };
}

/** Onboarding answers: null until the user picks. */
export type ConsentDraft = Record<ConsentType, boolean | null>;

export const EMPTY_DRAFT: Readonly<ConsentDraft> = Object.freeze({
  microphone: null,
  health: null,
  location: null,
});

export function answer(draft: ConsentDraft, type: ConsentType, allowed: boolean): ConsentDraft {
  return { ...draft, [type]: allowed };
}

/** The choices to send, or null while any type is unanswered. A missing answer is never a no. */
export function draftChoices(draft: ConsentDraft): ConsentChoices | null {
  const { microphone, health, location } = draft;
  if (microphone === null || health === null || location === null) return null;
  return { microphone, health, location };
}

/** `consent` with one type changed, for the Account tab. setConsent needs all three. */
export function withChoice(
  consent: ConsentChoices,
  type: ConsentType,
  allowed: boolean,
): ConsentChoices {
  return { ...consent, [type]: allowed };
}

/** One step per data type, then the Quiet Stays profile question. */
export const ONBOARDING_STEPS = [...CONSENT_TYPES, "profile"] as const;
export type OnboardingStep = (typeof ONBOARDING_STEPS)[number];

export type OnboardingWrites = {
  setProfile: (input: SetProfileInput) => Promise<AccountView>;
  setConsent: (input: SetConsentInput) => Promise<AccountView>;
};

/**
 * Saves onboarding. The profile goes first and consent last, because `consentUpdatedAt` is what
 * ends onboarding. If the consent write fails, the user stays in onboarding with the profile
 * already stored, and Finish saves both again.
 */
export async function saveOnboarding(
  writes: OnboardingWrites,
  answers: { consent: ConsentChoices; profile: TravellerProfile | null },
): Promise<AccountView> {
  if (answers.profile) await writes.setProfile({ profile: answers.profile });
  return writes.setConsent(answers.consent);
}

