    const lines = [...Object.values(WATCH_COPY), ...watchRows(READ).map((r) => `${r.label} ${r.value}`)];
    for (const line of lines) {
      expect(bannedWording(line)).toEqual([]);
      expect(line.includes("—")).toBe(false);
    }
  });
});

