import { z } from "zod";

/**
 * One Newcastle Urban Observatory noise sensor on the city map.
 * Figures are an indicative road-traffic estimate, never a measured disturbance rate
 * (`docs/DOMAIN.md`).
 */
export const sensorLevel = z
  .object({
    id: z.string().min(1),
    name: z.string().min(1),
    lat: z.number().min(-90).max(90),
    lon: z.number().min(-180).max(180),
    /** Energy average of nightly Lnight in dB; null when there is not enough data */
    lnight30: z.number().nullable(),
    /** Nights of data behind the estimate */
    nights: z.number().int().nonnegative(),
    /** Indicative % highly sleep disturbed from the WHO curve; null when there is not enough data */
    pctHighlySleepDisturbed: z.number().nullable(),
    /** Lnight fell outside 40 to 65 dB and was clamped for the estimate */
    outOfRange: z.boolean(),
    /** Fewer than 30 nights: show the sensor but don't shade it */
    notEnoughData: z.boolean(),
    indicative: z.literal(true),
    /** ISO 8601 timestamp of the latest reading used */
    updatedAt: z.iso.datetime(),
  })
  .refine((s) => !s.notEnoughData || (s.lnight30 === null && s.pctHighlySleepDisturbed === null), {
    message: "a sensor without enough data has no Lnight or %HSD",
  })
  .refine((s) => s.notEnoughData || (s.lnight30 !== null && s.pctHighlySleepDisturbed !== null), {
    message: "a sensor with enough data needs Lnight and %HSD",
  });
export type SensorLevel = z.infer<typeof sensorLevel>;

/** Output of the city sensors query. */
export const citySensors = z.array(sensorLevel);
export type CitySensors = z.infer<typeof citySensors>;
import { z } from "zod";
import { NOISE_LABELS } from "../domain";

/** One live reading: epoch seconds and relative dB (uncalibrated phone microphone, ~1 Hz) */
export const liveSample = z.object({
  t: z.number(),
  db: z.number(),
});
export type LiveSample = z.infer<typeof liveSample>;

/** A level above the rolling-median baseline by the spike threshold (docs/DOMAIN.md) */
export const liveSpike = z.object({
  t: z.number(),
  peakDb: z.number(),
  baselineDb: z.number(),
});
export type LiveSpike = z.infer<typeof liveSpike>;

/** A labelled spike, pushed to the web viewer; the briefing audio arrives once it is made */
export const liveEvent = z.object({
  spike: liveSpike,
  label: z.enum(NOISE_LABELS),
  /** Only meaningful for `construction`; "outside the council's recommended hours" in copy */
  outsideRecommendedHours: z.boolean(),
  briefingAudioUrl: z.url().nullable(),
});
export type LiveEvent = z.infer<typeof liveEvent>;

/** `live.push` input: a batch of samples from the iOS sender */
export const livePushInput = z.object({
  samples: z.array(liveSample).min(1),
});
export type LivePushInput = z.infer<typeof livePushInput>;

/** One item on the `live.stream` subscription */
export const liveStreamItem = z.discriminatedUnion("type", [
  z.object({ type: z.literal("sample"), sample: liveSample }),
  z.object({ type: z.literal("event"), event: liveEvent }),
]);
export type LiveStreamItem = z.infer<typeof liveStreamItem>;

