} from "@rnmapbox/maps";
import { type ComponentProps, useEffect, useMemo, useRef, useState } from "react";
import { StyleSheet } from "react-native";
import { MissingMapToken } from "./MissingMapToken";
import {
  cameraTracker,
  featuresToCollections,
  MAP_SOURCE,
  MAPBOX_STYLE,
